viewer.addEventListener('cancel',e=>{if(immersive){e.preventDefault();setImmersive(false);}});viewer.addEventListener('close',()=>{release();setImmersive(false);document.body.classList.remove('modal-open');history.replaceState(null,'',location.pathname+location.search);scrollTo(0,savedScroll);renderGrid();const target=originButton?.isConnected?originButton:[...gallery.children].find(node=>node.dataset.id===originId)?.querySelector('.entry-button');(target||$('#search')).focus({preventScroll:true});});
for(const id of ['depth','contour'])$('#'+id).oninput=e=>{$('#'+id+'-value').textContent=Number(e.target.value).toFixed(2)+'×';dirty=true;wake();};$('#reduce').onchange=e=>{reduced=e.target.checked;document.body.classList.toggle('motion-reduced',reduced);try{localStorage.setItem('holo-reduced',String(reduced));}catch{}if(reduced)stopMotion('已减少动态效果，仍可翻面和调节景深。');reset();dirty=true;wake();};
