$('#motion').onclick=async()=>{if(motion){stopMotion('感应已关闭，可拖动旋转。');reset();return;}if(reduced){hint('请先取消“减少动态效果”，再开启手机感应。');return;}if(!isSecureContext){hint('手机感应需要 HTTPS。');return;}if(!('DeviceOrientationEvent' in window)&&!('DeviceMotionEvent' in window)){hint('此设备不支持手机感应，可拖动旋转。');return;}const permission=++permissionTicket;try{let granted=true;if(typeof window.DeviceOrientationEvent?.requestPermission==='function')granted=await DeviceOrientationEvent.requestPermission()==='granted';else if(typeof window.DeviceMotionEvent?.requestPermission==='function')granted=await DeviceMotionEvent.requestPermission()==='granted';if(permission!==permissionTicket||!viewer.open)return;if(!granted){hint('未获得感应权限，可拖动旋转。');return;}motion=true;sensorOrigin=null;addEventListener('deviceorientation',orientation);addEventListener('devicemotion',gravity);$('#motion').textContent='关闭手机感应';$('#motion').setAttribute('aria-pressed','true');hint('等待手机感应数据…');sensorTimer=setTimeout(()=>stopMotion('未收到感应数据，请改用拖动。'),5000);}catch{stopMotion('感应无法开启，请使用手机浏览器重试或拖动。');}};
