gallery.addEventListener('keydown',e=>{const button=e.target.closest('.entry-button');if(!button||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();const position=filtered.findIndex(c=>c.id===button.closest('.entry').dataset.id),offset=gallery.getBoundingClientRect().top+scrollY,w=gridWindow(filtered.length,gallery.clientWidth,offset,scrollY,innerHeight);let next=position;if(e.key==='Home')next=0;else if(e.key==='End')next=filtered.length-1;else next+=({ArrowLeft:-1,ArrowRight:1,ArrowUp:-w.cols,ArrowDown:w.cols})[e.key];next=clamp(next,0,filtered.length-1);scrollTo({top:Math.max(0,offset+Math.floor(next/w.cols)*w.rowHeight-120),behavior:'instant'});renderGrid();gallery.querySelector(`[data-id="${filtered[next].id}"] .entry-button`)?.focus({preventScroll:true});});

